#!/usr/bin/env node
// Bakes the SDK version into the code at build time (npm "prebuild"): writes src/sdkVersion.generated.ts from the
// "version" of package.json — the TS twin of the Java SDK's sdk.properties, which Maven filters from pom.xml.
// SdkVersion reads the constant, so a module that BUNDLES the SDK (esbuild, ncc, …) carries the version and reads no
// file at run time (reading ../package.json through import.meta.url broke every bundle with ENOENT).
// The generated file is not committed (.gitignore): package.json stays the only place of the version.
//
//   node scripts/gen-version.mjs           # write src/sdkVersion.generated.ts
//   node scripts/gen-version.mjs --check   # exit 1 when the file is missing or differs from package.json
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = new URL('..', import.meta.url);
const pkg = JSON.parse(readFileSync(new URL('package.json', root), 'utf8'));
const version = typeof pkg.version === 'string' ? pkg.version.trim() : '';
if (!/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/.test(version)) {
  console.error(`gen-version: package.json has no semver "version" (${JSON.stringify(pkg.version)})`);
  process.exit(1);
}

const target = new URL('src/sdkVersion.generated.ts', root);
const text = [
  '// GENERATED by scripts/gen-version.mjs from package.json at build time (npm run build). Do not edit, not committed.',
  '// The TS twin of the Java SDK\'s Maven-filtered sdk.properties: the version is part of the code, so bundles carry it.',
  '',
  '/** The "version" of the SDK\'s package.json when it was built. */',
  `export const SDK_PACKAGE_VERSION = ${JSON.stringify(version)};`,
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : null;
  if (current !== text) {
    console.error(`gen-version: ${fileURLToPath(target)} is ${current === null ? 'missing' : 'stale'}; run npm run build`);
    process.exit(1);
  }
  console.log(`gen-version: ${version} ok`);
} else {
  writeFileSync(target, text);
  console.log(`gen-version: src/sdkVersion.generated.ts = ${version}`);
}
